
#' Obtain GWAS Catalog trait information from LDlink
#' 
#' Adds GWAS Catalog information associated with a trait or disease to a 'locus'
#' class object. It queries LDlink (https://ldlink.nci.nih.gov/) via the
#' `LDlinkR` package to retrieve GWAS Catolog information on a reference SNP.
#' 
#' @param loc Object of class 'locus' generated by [locus()]
#' @param pop A 1000 Genomes Project population, (e.g. YRI or CEU), multiple
#'   allowed, default = "CEU".
#' @param r2d Either "r2" for LD r^2 or "d" for LD D', default = "r2".
#' @param token Personal access token for accessing 1000 Genomes LD data via
#'   LDlink API. See `LDlinkR` package documentation.
#' @param genome_build Choose between one of the three options: 'grch37' for
#'   genome build GRCh37 (hg19), 'grch38' for GRCh38 (hg38), or
#'   'grch38_high_coverage' for GRCh38 High Coverage (hg38) 1000 Genome Project
#'   data sets.
#' @param ... Optional arguments passed on to `LDlinkR::LDtrait()`
#' @return Returns an object of class 'locus' with an extra list element 'LDtrait'
#'   containing a dataframe of information obtained via `LDtrait()`.

link_trait <- function(loc,
                       pop = "CEU",
                       r2d = "r2",
                       token = "",
                       genome_build = loc$genome, ...) {
  if (!inherits(loc, "locus")) stop("Not a locus object")
  if (!requireNamespace("LDlinkR", quietly = TRUE)) {
    stop("Package 'LDlinkR' must be installed to use this feature",
         call. = FALSE)
  }
  if (token == "") stop("token is missing")
  genome_build <- tolower(genome_build)
  if (!grepl(loc$genome, genome_build, ignore.case = TRUE)) {
    warning("mismatched genome build")
  }
  index_snp <- loc$index_snp
  snp_col <- if (grepl("rs", index_snp)) "RS_Number" else "Coord"
  emsg <- NULL
  
  start <- Sys.time()
  message("LDtrait ", index_snp, appendLF = FALSE)
  LDT <- suppressMessages(
    mem_LDtrait(index_snp, pop = pop, r2d = r2d, token = token,
                genome_build = genome_build, ...))
  if (ld_response_ok(LDT, c(snp_col, "GWAS_Trait"))) {
    for (i in c("R2", "D'", "P_value")) {
      LDT[, i] <- as.numeric(LDT[, i])
    }
    pos_col <- colnames(LDT)[grep("Position", colnames(LDT))]
    LDT$pos <- as.numeric(gsub(".*:", "", LDT[, pos_col]))  # remove up to ':'
    LDT$logP <- -log10(LDT$P_value)
  } else {
    emsg <- ld_response_error(LDT)
  }
  
  if (is.null(emsg)) {
    end <- Sys.time()
    LDT$indata <- LDT[, snp_col] %in% loc$data[, loc$labs]
    m <- length(unique(LDT[LDT$indata, snp_col]))
    a <- length(unique(LDT[, snp_col]))
    message(" - matched ", m, " of ", a, " trait SNPs (",
            format(end - start, digits = 3),")")
  } else {
    message("\n", if (is.na(emsg)) "Unexpected LDtrait response" else emsg)
  }
  
  loc$LDtrait <- LDT
  loc
}
  
mem_LDtrait <- memoise(LDlinkR::LDtrait)
